import RNA, random
def collect(target, n=12, seed0=1):
    sols=set()
    for s in range(n*5):
        random.seed(seed0+s)
        RNA.lock_seed_random() if hasattr(RNA,'lock_seed_random') else None
        try:
            seq = RNA.inverse_fold(target, "")[0]
        except Exception as e:
            seq=None
        if seq:
            # verify
            fc=RNA.fold_compound(seq)
            ss=fc.mfe()[0]
            if ss==target:
                sols.add(seq)
        if len(sols)>=n: break
    return list(sols)

